import {
  Entity,
  PrimaryGeneratedColumn,
  Column,
  CreateDateColumn,
  UpdateDateColumn,
  DeleteDateColumn,
} from 'typeorm';

@Entity('deals')
export class DealEntity {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @Column({ type: 'varchar', length: 255, comment: 'Deal name' })
  name: string;

  @Column({ type: 'double precision', comment: 'Deal value' })
  value: number;

  @Column({
    type: 'varchar',
    length: 100,
    default: 'lead',
    comment: 'Deal stage',
  })
  stage: string;

  @Column({ type: 'uuid', comment: 'Related company id' })
  companyId: string;

  @Column({ type: 'uuid', nullable: true, comment: 'Primary contact id' })
  primaryContactId: string | null;

  @Column({ type: 'date', nullable: true, comment: 'Expected close date' })
  expectedCloseDate: string | null;

  @CreateDateColumn({ type: 'timestamptz', comment: 'Creation timestamp' })
  createdAt: Date;

  @UpdateDateColumn({ type: 'timestamptz', comment: 'Update timestamp' })
  updatedAt: Date;

  @DeleteDateColumn({
    type: 'timestamptz',
    nullable: true,
    select: false,
    comment: 'Soft delete timestamp',
  })
  deletedAt: Date;
}

import { Type } from 'class-transformer';
import {
  IsArray,
  IsDateString,
  IsNotEmpty,
  IsNumber,
  IsOptional,
  IsString,
  IsUUID,
  MaxLength,
  Min,
  ValidateNested,
  ValidateIf,
} from 'class-validator';

export class DealContactLinkInputDto {
  @IsUUID('4', { message: 'contactLinks.contactId must be a valid UUID v4' })
  contactId: string;

  @IsOptional()
  @ValidateIf((_, value) => value !== null)
  @IsString()
  @MaxLength(255)
  role?: string | null;
}

export class CreateDealDto {
  @IsString()
  @IsNotEmpty()
  @MaxLength(255)
  name: string;

  @Type(() => Number)
  @IsNumber()
  @Min(0)
  value: number;

  @IsUUID('4', { message: 'companyId must be a valid UUID v4' })
  companyId: string;

  @IsOptional()
  @IsString()
  @IsNotEmpty()
  @MaxLength(100)
  stage?: string;

  @IsOptional()
  @IsArray()
  @ValidateNested({ each: true })
  @Type(() => DealContactLinkInputDto)
  contactLinks?: DealContactLinkInputDto[];

  @IsOptional()
  @ValidateIf((_, value) => value !== null)
  @IsUUID('4', { message: 'primaryContactId must be a valid UUID v4' })
  primaryContactId?: string | null;

  @IsOptional()
  @ValidateIf((_, value) => value !== null)
  @IsDateString()
  expectedCloseDate?: string | null;
}

