import {
  Body,
  Controller,
  Get,
  HttpCode,
  HttpStatus,
  Param,
  Post,
  Query,
} from '@nestjs/common';
import {
  CreateDealDto,
  DealIdParamDto,
  DealListQueryDto,
  UpdateDealDto,
} from './dto';
import { DealService } from './deal.service';

@Controller('deals')
export class DealController {
  constructor(private readonly dealService: DealService) {}

  @Post()
  async create(@Body() createDealDto: CreateDealDto) {
    return await this.dealService.createDeal(createDealDto);
  }

  @Get()
  async findAll(@Query() query: DealListQueryDto) {
    return await this.dealService.getDeals(query);
  }

  @Get(':id')
  async findOne(@Param() params: DealIdParamDto) {
    return await this.dealService.getDealWithCompany(params.id);
  }

  @Post(':id')
  @HttpCode(HttpStatus.OK)
  async update(
    @Param() params: DealIdParamDto,
    @Body() updateDealDto: UpdateDealDto,
  ) {
    return await this.dealService.updateDeal(params.id, updateDealDto);
  }
}

import { Type } from 'class-transformer';
import { IsInt, IsOptional, IsString, IsUUID, Min } from 'class-validator';

export class DealListQueryDto {
  @IsOptional()
  @Type(() => Number)
  @IsInt()
  @Min(1)
  page: number = 1;

  @IsOptional()
  @Type(() => Number)
  @IsInt()
  @Min(10)
  pageSize: number = 10;

  @IsOptional()
  @IsString()
