import { INestApplication } from '@nestjs/common';
import { DataSource } from 'typeorm';
import request from 'supertest';
import { createTestApp } from './setup/test-app';
import {
  closeTestDataSource,
  resetDatabaseSchema,
  truncateBusinessTables,
} from './setup/test-database';

jest.setTimeout(30000);

describe('Deal API (e2e)', () => {
  let app: INestApplication;
  let dataSource: DataSource;
  let companySeq = 0;
  let contactSeq = 0;
  let dealSeq = 0;

  beforeAll(async () => {
    await resetDatabaseSchema();
    app = await createTestApp();
    dataSource = app.get(DataSource);
    await truncateBusinessTables(dataSource);
  });

  afterAll(async () => {
    if (app) {
      await app.close();
    }

    await closeTestDataSource();
  });

  it('creates a deal with multiple contacts and returns primaryContactId/contactLinks', async () => {
    // Verifies deal create supports many contact links and primary contact tracking.
    const companyId = await createCompany('deal-create');
    const contactA = await createContact('deal-create-a', companyId);
    const contactB = await createContact('deal-create-b', companyId);

    const payload = buildDealPayload('create', {
      companyId,
      contactLinks: [
        { contactId: contactA, role: 'decision-maker' },
        { contactId: contactB, role: 'legal' },
      ],
      primaryContactId: contactA,
      stage: 'qualified',
      expectedCloseDate: '2026-09-30',
    });

    const createResponse = await request(app.getHttpServer())
      .post('/api/deals')
      .send(payload)
      .expect(201);

    expect(createResponse.body).toMatchObject({
      name: payload.name,
      companyId,
      primaryContactId: contactA,
      contactLinks: [
        { contactId: contactA, role: 'decision-maker' },
        { contactId: contactB, role: 'legal' },
      ],
    });
    expect(createResponse.body).not.toHaveProperty('contactId');

    const detailResponse = await request(app.getHttpServer())
      .get(`/api/deals/${createResponse.body.id}`)
      .expect(200);

    expect(detailResponse.body).toMatchObject({
      id: createResponse.body.id,
      companyId,
      primaryContactId: contactA,
      contactLinks: [
        { contactId: contactA, role: 'decision-maker' },
        { contactId: contactB, role: 'legal' },
      ],
      company: {
        id: companyId,
        name: expect.stringContaining('codex-e2e-company-deal-create'),
      },
    });
    expect(detailResponse.body).not.toHaveProperty('contactId');
  });

  it('supports deals with zero linked contacts', async () => {
    // Verifies empty contact link sets are valid for create and read.
    const companyId = await createCompany('deal-empty-contacts');
    const payload = buildDealPayload('empty-contacts', {
      companyId,
      contactLinks: [],
      primaryContactId: null,
    });

    const createResponse = await request(app.getHttpServer())
      .post('/api/deals')
      .send(payload)
      .expect(201);

    expect(createResponse.body).toMatchObject({
      primaryContactId: null,
      contactLinks: [],
    });
  });

  it('rejects primaryContactId when not present in contactLinks', async () => {
    // Verifies primary contact must be selected from the deal contactLinks set.
    const companyId = await createCompany('deal-primary-validation');
    const contactA = await createContact(
      'deal-primary-validation-a',
      companyId,
    );
    const contactB = await createContact(
      'deal-primary-validation-b',
      companyId,
    );

    const response = await request(app.getHttpServer())
      .post('/api/deals')
      .send(
        buildDealPayload('primary-validation', {
          companyId,
          contactLinks: [{ contactId: contactA, role: 'owner' }],
          primaryContactId: contactB,
        }),
      )
      .expect(400);

    expect(response.body).toMatchObject({
      success: false,
      statusCode: 400,
      code: 'VALIDATION_ERROR',
    });
  });

  it('returns NOT_FOUND for unknown companyId or contactId', async () => {
    // Verifies deal links require existing company/contact references.
    const missingCompanyResponse = await request(app.getHttpServer())
      .post('/api/deals')
      .send(
        buildDealPayload('missing-company', {
          companyId: '7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1aa',
        }),
      )
      .expect(404);

    expect(missingCompanyResponse.body).toMatchObject({
      success: false,
      statusCode: 404,
      code: 'NOT_FOUND',
    });

    const companyId = await createCompany('missing-contact');
    const missingContactResponse = await request(app.getHttpServer())
      .post('/api/deals')
      .send(
        buildDealPayload('missing-contact', {
          companyId,
          contactLinks: [
            {
              contactId: '7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1bb',
              role: 'owner',
            },
          ],
          primaryContactId: '7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1bb',
        }),
      )
      .expect(404);

    expect(missingContactResponse.body).toMatchObject({
      success: false,
      statusCode: 404,
      code: 'NOT_FOUND',
    });
  });

  it('supports pagination and stage/company filtering', async () => {
    // Verifies list endpoint keeps existing filtering semantics.
    const companyId = await createCompany('list-main');
    const otherCompanyId = await createCompany('list-other');
    await createDeal('list-a', { companyId, stage: 'qualified' });
    await createDeal('list-b', { companyId, stage: 'qualified' });
    await createDeal('list-c', { companyId, stage: 'negotiation' });
    await createDeal('list-d', {
      companyId: otherCompanyId,
      stage: 'qualified',
    });

    const filtered = await request(app.getHttpServer())
      .get(
        `/api/deals?companyId=${companyId}&stage=qualified&page=1&pageSize=10`,
      )
      .expect(200);

    expect(filtered.body).toMatchObject({
      total: 2,
      page: 1,
      pageSize: 10,
      totalPages: 1,
    });
    expect(filtered.body.items).toHaveLength(2);
    expect(
      filtered.body.items.every(
        (item: { stage: string; companyId: string }) =>
          item.stage === 'qualified' && item.companyId === companyId,
      ),
    ).toBe(true);
    expect(
      filtered.body.items.every(
        (item: { contactId?: string }) => !('contactId' in item),
      ),
    ).toBe(true);
  });

  it('updates contactLinks and primaryContactId atomically', async () => {
    // Verifies update can replace full contact links + primary in one request.
    const companyId = await createCompany('update');
    const contactA = await createContact('update-a', companyId);
    const contactB = await createContact('update-b', companyId);
    const contactC = await createContact('update-c', companyId);

    const dealId = await createDeal('update', {
      companyId,
      contactLinks: [{ contactId: contactA, role: 'owner' }],
      primaryContactId: contactA,
    });

    const updateResponse = await request(app.getHttpServer())
      .post(`/api/deals/${dealId}`)
      .send({
        stage: 'negotiation',
        contactLinks: [
          { contactId: contactB, role: 'legal' },
          { contactId: contactC, role: 'it' },
        ],
        primaryContactId: contactB,
      })
      .expect(200);

    expect(updateResponse.body).toMatchObject({
      id: dealId,
      stage: 'negotiation',
      primaryContactId: contactB,
      contactLinks: [
        { contactId: contactB, role: 'legal' },
        { contactId: contactC, role: 'it' },
      ],
    });
    expect(updateResponse.body).not.toHaveProperty('contactId');
  });

  it('rejects replacing links with unknown contacts and keeps existing data', async () => {
    // Verifies unknown contact ids fail the update without mutating persisted links.
    const companyId = await createCompany('update-rollback');
    const contactA = await createContact('update-rollback-a', companyId);

    const dealId = await createDeal('update-rollback', {
      companyId,
      contactLinks: [{ contactId: contactA, role: 'owner' }],
      primaryContactId: contactA,
    });

    const failedUpdate = await request(app.getHttpServer())
      .post(`/api/deals/${dealId}`)
      .send({
        contactLinks: [
          {
            contactId: '7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1ff',
            role: 'unknown',
          },
        ],
        primaryContactId: '7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1ff',
      })
      .expect(404);

    expect(failedUpdate.body).toMatchObject({
      success: false,
      statusCode: 404,
      code: 'NOT_FOUND',
    });

    const detail = await request(app.getHttpServer())
      .get(`/api/deals/${dealId}`)
      .expect(200);

    expect(detail.body).toMatchObject({
      primaryContactId: contactA,
      contactLinks: [{ contactId: contactA, role: 'owner' }],
    });
  });

  async function createCompany(scope: string): Promise<string> {
    companySeq += 1;

    const response = await request(app.getHttpServer())
      .post('/api/companies')
      .send({
        name: `codex-e2e-company-${scope}-${companySeq}`,
        email: `deal-company-${companySeq}@test.local`,
        phone: `0100-${String(companySeq).padStart(4, '0')}`,
        website: `https://deal-company-${companySeq}.example.com`,
      })
      .expect(201);

    return response.body.companyId;
  }

  async function createContact(
    scope: string,
    companyId: string,
  ): Promise<string> {
    contactSeq += 1;

    const response = await request(app.getHttpServer())
      .post('/api/contacts')
      .send({
        companies: [{ id: companyId, isPrimary: true }],
        name: `codex-e2e-contact-${scope}-${contactSeq}`,
        email: `deal-contact-${contactSeq}@test.local`,
        phone: `0200-${String(contactSeq).padStart(4, '0')}`,
        role: 'Decision Maker',
      })
      .expect(201);

    return response.body.id;
  }

  async function createDeal(
    scope: string,
    overrides: Partial<DealPayload> = {},
  ): Promise<string> {
    const payload = buildDealPayload(scope, overrides);
    const response = await request(app.getHttpServer())
      .post('/api/deals')
      .send(payload)
      .expect(201);

    return response.body.id;
  }

  function buildDealPayload(
    scope: string,
    overrides: Partial<DealPayload> = {},
  ): DealPayload {
    dealSeq += 1;

    return {
      name: `codex-e2e-deal-${scope}-${dealSeq}`,
      value: 10000 + dealSeq,
      companyId: '00000000-0000-4000-8000-000000000001',
      stage: 'lead',
      contactLinks: [],
      primaryContactId: null,
      expectedCloseDate: null,
      ...overrides,
    };
  }
});

