function extractErrorMessage(error, fallbackMessage) {
  return error?.message || fallbackMessage;
}

export default function DealsPage() {
  const navigate = useNavigate();
  const createDeal = useCreateDeal();
  const updateDeal = useUpdateDeal();

  const [feedback, setFeedback] = useState({
    open: false,
    severity: 'success',
    message: '',
  });
  const [formState, setFormState] = useState({
    open: false,
    mode: 'create',
    deal: null,
  });
  const [stageInput, setStageInput] = useState('');
  const [companyInput, setCompanyInput] = useState('');
  const [listQuery, setListQuery] = useState({
    page: 1,
    pageSize: 10,
  });

  const dealsQuery = useDealList(listQuery);
  const companiesQuery = useCompanyList({ page: 1, pageSize: 100 });

  const companyOptions = companiesQuery.data?.items ?? [];
  const companiesById = useMemo(
    () =>
      Object.fromEntries(companyOptions.map((company) => [company.id, company.name])),
    [companyOptions],
  );

  const handleSubmit = async (payload) => {
    try {
      if (formState.mode === 'create') {
        await createDeal.mutateAsync(payload);
        setFeedback({
          open: true,
          severity: 'success',
          message: 'Deal created.',
        });
      } else {
        await updateDeal.mutateAsync({
          id: formState.deal.id,
          data: payload,
        });
        setFeedback({
          open: true,
          severity: 'success',
          message: 'Deal updated.',
        });
      }

      setFormState({ open: false, mode: 'create', deal: null });
    } catch (error) {
      if (!isTransportError(error)) {
        setFeedback({
          open: true,
          severity: 'error',
          message: extractErrorMessage(error, 'Deal request failed.'),
        });
      }
    }
  };

  const handleSearchSubmit = (event) => {
    event.preventDefault();
    setListQuery((current) => ({
      ...current,
      page: 1,
      ...(stageInput.trim() ? { stage: stageInput.trim() } : { stage: undefined }),
      ...(companyInput ? { companyId: companyInput } : { companyId: undefined }),
    }));
  };

  const handleResetFilters = () => {
    setStageInput('');
    setCompanyInput('');
    setListQuery((current) => ({ page: 1, pageSize: current.pageSize }));
  };

  const dealPage = dealsQuery.data;
  const deals = dealPage?.items ?? [];

  return (
    <Stack spacing={3}>
      <DataTableShell
        title="Deals"
        searchValue={stageInput}
        onSearchChange={setStageInput}
        onSearchSubmit={handleSearchSubmit}
        onReset={handleResetFilters}
        searchPlaceholder="Filter by stage (exact)"
        filters={(
          <TextField
            select
            size="small"
            label="Company"
            value={companyInput}
            onChange={(event) => setCompanyInput(event.target.value)}
            sx={{ minWidth: '14rem' }}
          >
            <MenuItem value="">All companies</MenuItem>
            {companyOptions.map((company) => (
              <MenuItem key={company.id} value={company.id}>
                {company.name}
              </MenuItem>
            ))}
          </TextField>
        )}
        actions={(
          <Button
            variant="contained"
            startIcon={<PlusOutlined />}
            onClick={() =>
              setFormState({ open: true, mode: 'create', deal: null })
            }
          >
            Add Deal
          </Button>
        )}
        loading={dealsQuery.isLoading}
        error={
          dealsQuery.isError && !isTransportError(dealsQuery.error)
            ? extractErrorMessage(dealsQuery.error, 'Failed to load deals.')
            : null
        }
        isEmpty={!dealsQuery.isLoading && !dealsQuery.isError && deals.length === 0}
        emptyTitle="No matching deals"
        emptyDescription="Try broadening stage/company filters or clearing filters."
        pagination={
          dealPage && dealPage.total > 0 ? (
            <Box sx={{ display: 'flex', width: '100%', justifyContent: 'center' }}>
              <DataTablePagination
                page={dealPage.page}
                pageSize={dealPage.pageSize}
                total={dealPage.total}
                totalPages={dealPage.totalPages}
                onPageChange={(page) =>
                  setListQuery((current) => ({ ...current, page }))
                }
                onPageSizeChange={(pageSize) =>
                  setListQuery((current) => ({ ...current, page: 1, pageSize }))
                }
              />
            </Box>
          ) : null
        }
      >
        <DealTable
          deals={deals}
          companiesById={companiesById}
          onView={(deal) => navigate(`/deals/${deal.id}`)}
          onEdit={(deal) => setFormState({ open: true, mode: 'edit', deal })}
        />
      </DataTableShell>

      <DealFormDialog
        open={formState.open}
        mode={formState.mode}
        initialValues={formState.deal}
        isPending={createDeal.isPending || updateDeal.isPending}
        onClose={() => setFormState({ open: false, mode: 'create', deal: null })}
        onSubmit={handleSubmit}
      />

      <Snackbar
        open={feedback.open}
        autoHideDuration={3200}
        onClose={() => setFeedback((current) => ({ ...current, open: false }))}
      >
        <Alert
          onClose={() => setFeedback((current) => ({ ...current, open: false }))}
          severity={feedback.severity}
          variant="filled"
        >
          {feedback.message}
        </Alert>
      </Snackbar>
    </Stack>
  );
