const emptyValues = {
  companyId: '',
  contactLinks: [],
  primaryContactId: null,
  name: '',
  stage: 'lead',
  value: '',
  expectedCloseDate: '',
};
const stageOptions = [
  'lead',
  'qualified',
  'proposal',
  'negotiation',
  'closed-won',
  'closed-lost',
];

function normalizeCloseDate(value) {
  if (!value) {
    return '';
  }

  if (/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return value;
  }

  return formatForDatetimeLocal(value).slice(0, 10);
}

function normalizeContactLinks(initialValues) {
  if (Array.isArray(initialValues?.contactLinks)) {
    return initialValues.contactLinks.map((link) => ({
      contactId: link.contactId,
      role: link.role ?? '',
    }));
  }

  if (initialValues?.contactId) {
    return [{ contactId: initialValues.contactId, role: '' }];
  }

  return [];
}

export function DealFormDialog({
  initialValues,
  isPending,
  mode,
  onClose,
  onSubmit,
  open,
}) {
  const [values, setValues] = useState(emptyValues);
  const [touched, setTouched] = useState({
    companyId: false,
    name: false,
    stage: false,
    value: false,
  });

  const companiesQuery = useCompanyList({ page: 1, pageSize: 100 });
  const contactsQuery = useContactList({
    companyId: values.companyId || undefined,
    page: 1,
    pageSize: 100,
  });

  const companyOptions = companiesQuery.data?.items ?? [];
  const contactOptions = values.companyId ? contactsQuery.data?.items ?? [] : [];

  const selectedCompany =
    companyOptions.find((company) => company.id === values.companyId) ?? null;

  const selectedContacts = useMemo(
    () =>
      values.contactLinks
        .map((link) =>
          contactOptions.find((contact) => contact.id === link.contactId),
        )
        .filter(Boolean),
    [contactOptions, values.contactLinks],
  );

  const parsedValue = Number(values.value);
  const isValueValid =
    values.value !== '' && Number.isFinite(parsedValue) && parsedValue >= 0;
  const linkedContactIds = new Set(
    values.contactLinks.map((contactLink) => contactLink.contactId),
  );

  const errors = {
    companyId: !values.companyId ? 'Company is required.' : '',
    name: !values.name?.trim()
      ? 'Name is required.'
      : values.name.trim().length > 255
        ? 'Name must be 255 characters or fewer.'
        : '',
    stage: !values.stage?.trim()
      ? 'Stage is required.'
      : values.stage.trim().length > 100
        ? 'Stage must be 100 characters or fewer.'
        : '',
    value:
      values.value === ''
        ? 'Value is required.'
        : !isValueValid
          ? 'Value must be a non-negative number.'
          : '',
    primaryContactId:
      values.primaryContactId && !linkedContactIds.has(values.primaryContactId)
        ? 'Primary contact must be one of the linked contacts.'
        : '',
  };

  const isFormValid =
    !errors.companyId &&
    !errors.name &&
    !errors.stage &&
    !errors.value &&
    !errors.primaryContactId;

  useEffect(() => {
    if (!open) {
      return;
    }

    const initialContactLinks = normalizeContactLinks(initialValues);
    const initialPrimaryContactId =
      initialValues?.primaryContactId ?? initialValues?.contactId ?? null;

    setValues({
      ...emptyValues,
      ...initialValues,
      companyId: initialValues?.companyId || '',
      contactLinks: initialContactLinks,
      primaryContactId:
        initialPrimaryContactId &&
        initialContactLinks.some(
          (contactLink) => contactLink.contactId === initialPrimaryContactId,
        )
          ? initialPrimaryContactId
          : initialContactLinks.length === 1
            ? initialContactLinks[0].contactId
            : null,
      stage: initialValues?.stage || 'lead',
      value:
        initialValues?.value === null || initialValues?.value === undefined
          ? ''
          : String(initialValues.value),
      expectedCloseDate: normalizeCloseDate(initialValues?.expectedCloseDate),
    });
    setTouched({ companyId: false, name: false, stage: false, value: false });
  }, [initialValues, open]);

  useEffect(() => {
    if (values.contactLinks.length === 0) {
      if (values.primaryContactId) {
        setValues((current) => ({ ...current, primaryContactId: null }));
      }
      return;
    }

    const selectedContactIds = new Set(contactOptions.map((contact) => contact.id));
    const prunedLinks = values.contactLinks.filter((contactLink) =>
      selectedContactIds.has(contactLink.contactId),
    );

    if (prunedLinks.length !== values.contactLinks.length) {
      setValues((current) => {
        const nextPrimary = prunedLinks.some(
          (contactLink) => contactLink.contactId === current.primaryContactId,
        )
          ? current.primaryContactId
          : prunedLinks.length === 1
            ? prunedLinks[0].contactId
            : null;

        return {
          ...current,
          contactLinks: prunedLinks,
          primaryContactId: nextPrimary,
        };
      });
    }
  }, [contactOptions, values.contactLinks, values.primaryContactId]);

  const handleChange = (field) => (event) => {
    setValues((current) => ({ ...current, [field]: event.target.value }));
  };

  const handleBlur = (field) => () => {
    setTouched((current) => ({ ...current, [field]: true }));
  };

  const handleCompanyChange = (_, company) => {
    setValues((current) => ({
      ...current,
      companyId: company?.id || '',
      contactLinks: [],
      primaryContactId: null,
    }));
  };

  const handleContactsChange = (_, selectedContactOptions) => {
    const selectedContactIds = selectedContactOptions.map((contact) => contact.id);

    setValues((current) => {
      const previousById = new Map(
        current.contactLinks.map((contactLink) => [contactLink.contactId, contactLink]),
      );

      const nextContactLinks = selectedContactIds.map((contactId) => ({
        contactId,
        role: previousById.get(contactId)?.role ?? '',
      }));

      const currentPrimaryStillSelected =
        current.primaryContactId && selectedContactIds.includes(current.primaryContactId)
          ? current.primaryContactId
          : null;

      return {
        ...current,
        contactLinks: nextContactLinks,
        primaryContactId:
          currentPrimaryStillSelected ||
          (nextContactLinks.length === 1 ? nextContactLinks[0].contactId : null),
      };
    });
  };

  const handleContactRoleChange = (contactId, role) => {
    setValues((current) => ({
      ...current,
      contactLinks: current.contactLinks.map((contactLink) =>
        contactLink.contactId === contactId
          ? { ...contactLink, role }
          : contactLink,

          : contactLink,
      ),
    }));
  };

  const handlePrimaryContactChange = (contactId) => {
    setValues((current) => ({
      ...current,
      primaryContactId:
        current.primaryContactId === contactId ? null : contactId,
    }));
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setTouched({ companyId: true, name: true, stage: true, value: true });

    if (!isFormValid) {
      return;
    }

    const payload = {
      name: values.name.trim(),
      value: Number(values.value),
      stage: values.stage.trim(),
      contactLinks: values.contactLinks.map((contactLink) => ({
        contactId: contactLink.contactId,
        role: contactLink.role?.trim() || null,
      })),
      primaryContactId: values.primaryContactId,
      expectedCloseDate: values.expectedCloseDate || null,
    };

    if (mode === 'create') {
      await onSubmit({
        ...payload,
        companyId: values.companyId,
      });
      return;
    }

    await onSubmit(payload);
  };

  return (
    <Dialog
      open={open}
      onClose={isPending ? undefined : onClose}
      fullWidth
      maxWidth="md"
    >
      <DialogTitle>{mode === 'create' ? 'Create deal' : 'Edit deal'}</DialogTitle>

      <DialogContent sx={{ p: 2.5 }}>
        <Stack component="form" spacing={2} onSubmit={handleSubmit} sx={{ mt: 1 }}>
          <TextField
            required
            autoFocus
            label="Deal name"
            value={values.name}
            onBlur={handleBlur('name')}
            onChange={handleChange('name')}
            error={touched.name && Boolean(errors.name)}
            helperText={touched.name ? errors.name : undefined}
          />

          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
            <TextField
              required
              fullWidth
              label="Value"
              type="number"
              slotProps={{ htmlInput: { min: 0, step: '0.01' } }}
              value={values.value}
              onBlur={handleBlur('value')}
              onChange={handleChange('value')}
              error={touched.value && Boolean(errors.value)}
              helperText={touched.value ? errors.value : undefined}
            />

            <TextField
              required
              fullWidth
              label="Stage"
              value={values.stage}
              onBlur={handleBlur('stage')}
              onChange={handleChange('stage')}
              error={touched.stage && Boolean(errors.stage)}
              helperText={touched.stage ? errors.stage : undefined}
              select
            >
              {stageOptions.map((stage) => (
                <MenuItem key={stage} value={stage}>
                  {stage}
                </MenuItem>
              ))}
            </TextField>
          </Stack>

          <Autocomplete
            fullWidth
            options={companyOptions}
            value={selectedCompany}
            loading={companiesQuery.isLoading}
            onBlur={handleBlur('companyId')}
            onChange={handleCompanyChange}
            disabled={mode === 'edit'}
            isOptionEqualToValue={(option, value) => option.id === value.id}
            getOptionLabel={(option) => option?.name || ''}
            noOptionsText={
              companiesQuery.isLoading ? 'Loading companies...' : 'No companies found'
            }
            renderInput={(params) => (
              <TextField
                {...params}
                required
                label="Company"
                error={touched.companyId && Boolean(errors.companyId)}
                helperText={
                  touched.companyId
                    ? errors.companyId
                    : companiesQuery.isError
                      ? 'Failed to load companies.'
                      : mode === 'edit'
                        ? 'Company is immutable once a deal is created.'
                        : undefined
                }
                InputProps={{
                  ...params.InputProps,
                  endAdornment: (
                    <>
                      {companiesQuery.isLoading ? (
                        <CircularProgress color="inherit" size={20} />
                      ) : null}
                      {params.InputProps.endAdornment}
                    </>
                  ),
                }}
              />
            )}
          />

          <Autocomplete
            multiple
            fullWidth
            options={contactOptions}
            value={selectedContacts}
            loading={contactsQuery.isLoading && Boolean(values.companyId)}
            disabled={!values.companyId}
            onChange={handleContactsChange}
            isOptionEqualToValue={(option, value) => option.id === value.id}
            getOptionLabel={(option) => option?.name || ''}
            noOptionsText={
              !values.companyId
                ? 'Select a company first'
                : contactsQuery.isLoading
                  ? 'Loading contacts...'
                  : 'No contacts found'
            }
            renderInput={(params) => (
              <TextField
                {...params}
                label="Linked contacts"
                helperText={
                  contactsQuery.isError && values.companyId
                    ? 'Failed to load contacts.'
                    : 'Deals can have zero or more contacts.'
                }
                InputProps={{
                  ...params.InputProps,
                  endAdornment: (
                    <>
                      {contactsQuery.isLoading && values.companyId ? (
                        <CircularProgress color="inherit" size={20} />
                      ) : null}
                      {params.InputProps.endAdornment}
                    </>
                  ),
                }}
              />
            )}
          />

          {values.contactLinks.length > 0 ? (
            <Stack spacing={1.25}>
              <Typography variant="subtitle2" color="text.secondary">
                Contact roles and primary
              </Typography>

              {values.contactLinks.map((contactLink) => {
                const contactName =
                  contactOptions.find((contact) => contact.id === contactLink.contactId)
                    ?.name || contactLink.contactId;

                return (
                  <Stack
                    key={contactLink.contactId}
                    direction={{ xs: 'column', md: 'row' }}
                    spacing={1.5}
                    sx={{ alignItems: { md: 'center' } }}
                  >
                    <Typography sx={{ minWidth: { md: '14rem' } }}>{contactName}</Typography>
                    <TextField
                      fullWidth
                      label="Role (optional)"
                      value={contactLink.role}
                      onChange={(event) =>
                        handleContactRoleChange(contactLink.contactId, event.target.value)
                      }
                    />
                    <FormControlLabel
                      control={
                        <Radio
                          checked={values.primaryContactId === contactLink.contactId}
                          onChange={() =>
                            handlePrimaryContactChange(contactLink.contactId)
                          }
                        />
                      }
                      label="Primary"
                    />
                  </Stack>
                );
              })}

              {errors.primaryContactId ? (
                <Typography color="error" variant="caption">
                  {errors.primaryContactId}
                </Typography>
              ) : null}
            </Stack>
          ) : null}

          <TextField
            fullWidth
            label="Expected close date"
            type="date"
            InputLabelProps={{ shrink: true }}
            value={values.expectedCloseDate}
            onChange={handleChange('expectedCloseDate')}
          />

          <button type="submit" hidden />
        </Stack>
      </DialogContent>

      <DialogActions className="crm-dialog-actions">
        <Button onClick={onClose} disabled={isPending}>
          Cancel
        </Button>
        <Button variant="contained" onClick={handleSubmit} disabled={isPending}>
          {mode === 'create' ? 'Create' : 'Save'}
        </Button>
      </DialogActions>
    </Dialog>
  );
}

import Box from '@mui/material/Box';
import Chip from '@mui/material/Chip';
import CircularProgress from '@mui/material/CircularProgress';
import Stack from '@mui/material/Stack';
import Typography from '@mui/material/Typography';
import ArrowLeftOutlined from '@ant-design/icons/ArrowLeftOutlined';
import { useQueries } from '@tanstack/react-query';
import { Link, useParams } from 'react-router-dom';

import MainCard from 'components/MainCard';
import IconButton from 'components/IconButton';
import { contactApi } from 'api/contactApi';
import { isTransportError } from 'api/request';
import formatDate from 'utils/formatDate';
import { useDeal } from './dealQueries';

function formatCurrency(value) {
  if (value === null || value === undefined || Number.isNaN(Number(value))) {
    return '—';
  }

  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    maximumFractionDigits: 0,
  }).format(Number(value));
}

function DetailRow({ label, value }) {
  return (
    <Stack direction="row" spacing={2} sx={{ justifyContent: 'space-between' }}>
      <Typography color="text.secondary">{label}</Typography>
      <Typography>{value || '—'}</Typography>
    </Stack>
  );
}

function DealContacts({ deal, contactNameById }) {
  if (!deal?.contactLinks?.length) {
    return <DetailRow label="Contacts" value="—" />;
  }

  return (
    <Stack spacing={1}>
      <Typography color="text.secondary">Contacts</Typography>
      {deal.contactLinks.map((contactLink) => {
        const contactName =
          contactNameById.get(contactLink.contactId) || contactLink.contactId;

        return (
          <Stack
            key={contactLink.contactId}
            direction="row"
            spacing={1.5}
            sx={{ justifyContent: 'space-between', alignItems: 'center' }}
          >
            <Stack direction="row" spacing={1} alignItems="center">
              <Typography>{contactName}</Typography>
              {deal.primaryContactId === contactLink.contactId ? (
                <Chip size="small" color="success" label="Primary" />
              ) : null}
            </Stack>
            <Typography color="text.secondary">
              {contactLink.role || 'No role'}
            </Typography>
          </Stack>
        );
      })}
    </Stack>
  );
}

export default function DealDetail() {
  const { id } = useParams();
  const dealQuery = useDeal(id);
  const deal = dealQuery.data;

  const contactQueries = useQueries({
    queries: (deal?.contactLinks ?? []).map((contactLink) => ({
      queryKey: ['contacts', 'detail', contactLink.contactId],
      queryFn: () => contactApi.get(contactLink.contactId),
    })),
  });

  const contactNameById = new Map(
    contactQueries
      .map((query) => query.data)
      .filter(Boolean)
      .map((contact) => [contact.id, contact.name]),
  );

  return (
    <Stack spacing={2}>
      <IconButton component={Link} to="/deals" aria-label="Back to deals" shape="rounded">
        <ArrowLeftOutlined />
      </IconButton>

      <MainCard title={deal?.name || 'Deal detail'}>
        {dealQuery.isLoading ? (
          <Box sx={{ display: 'flex', justifyContent: 'center', py: 3 }}>
            <CircularProgress />
          </Box>
        ) : null}

        {dealQuery.isError && !isTransportError(dealQuery.error) ? (
          <Typography color="error">{dealQuery.error?.message || 'Failed to load deal.'}</Typography>
        ) : null}

        {deal ? (
          <Stack spacing={1.5}>
            <DetailRow label="ID" value={deal.id} />
            <DetailRow label="Company" value={deal.company?.name || deal.companyId} />
            <DetailRow label="Stage" value={deal.stage} />
            <DetailRow label="Value" value={formatCurrency(deal.value)} />
            <DealContacts deal={deal} contactNameById={contactNameById} />
            <DetailRow label="Expected Close" value={formatDate(deal.expectedCloseDate)} />
            <DetailRow label="Created" value={formatDate(deal.createdAt)} />
            <DetailRow label="Updated" value={formatDate(deal.updatedAt)} />
          </Stack>
        ) : null}
      </MainCard>
    </Stack>
  );
}

import {
  Alert,
  Box,
  Button,
  MenuItem,
  Snackbar,
  Stack,
  TextField,
} from '@mui/material';
import PlusOutlined from '@ant-design/icons/PlusOutlined';
import { useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';

import { isTransportError } from 'api/request';
import { DataTablePagination } from '../../components/Table/Pagination/Pagination';
import { DataTableShell } from '../../components/Table/Shell/Shell';
import { useCompanyList } from '../companies/companyQueries';
import { DealFormDialog } from './DealForm';
import { DealTable } from './DealTable';
import { useCreateDeal, useDealList, useUpdateDeal } from './dealQueries';

function extractErrorMessage(error, fallbackMessage) {
  return error?.message || fallbackMessage;
}

export default function DealsPage() {
  const navigate = useNavigate();
  const createDeal = useCreateDeal();
  const updateDeal = useUpdateDeal();

  const [feedback, setFeedback] = useState({
    open: false,
    severity: 'success',
    message: '',
  });
  const [formState, setFormState] = useState({
    open: false,
    mode: 'create',
    deal: null,
  });
  const [stageInput, setStageInput] = useState('');
  const [companyInput, setCompanyInput] = useState('');
  const [listQuery, setListQuery] = useState({
    page: 1,
    pageSize: 10,
  });

  const dealsQuery = useDealList(listQuery);
  const companiesQuery = useCompanyList({ page: 1, pageSize: 100 });

  const companyOptions = companiesQuery.data?.items ?? [];
  const companiesById = useMemo(
    () =>
      Object.fromEntries(companyOptions.map((company) => [company.id, company.name])),
    [companyOptions],
  );

  const handleSubmit = async (payload) => {
    try {
      if (formState.mode === 'create') {
        await createDeal.mutateAsync(payload);
        setFeedback({
          open: true,
          severity: 'success',
          message: 'Deal created.',
        });
      } else {
        await updateDeal.mutateAsync({
          id: formState.deal.id,
          data: payload,
        });
        setFeedback({
          open: true,
          severity: 'success',
          message: 'Deal updated.',
        });
      }

      setFormState({ open: false, mode: 'create', deal: null });
    } catch (error) {
      if (!isTransportError(error)) {
        setFeedback({
          open: true,
          severity: 'error',
          message: extractErrorMessage(error, 'Deal request failed.'),
        });
      }
    }
  };

  const handleSearchSubmit = (event) => {
    event.preventDefault();
    setListQuery((current) => ({
      ...current,
      page: 1,
      ...(stageInput.trim() ? { stage: stageInput.trim() } : { stage: undefined }),
      ...(companyInput ? { companyId: companyInput } : { companyId: undefined }),
    }));
  };

  const handleResetFilters = () => {
    setStageInput('');
    setCompanyInput('');
    setListQuery((current) => ({ page: 1, pageSize: current.pageSize }));
  };

  const dealPage = dealsQuery.data;
  const deals = dealPage?.items ?? [];

  return (
    <Stack spacing={3}>
      <DataTableShell
        title="Deals"
        searchValue={stageInput}
        onSearchChange={setStageInput}
        onSearchSubmit={handleSearchSubmit}
        onReset={handleResetFilters}
        searchPlaceholder="Filter by stage (exact)"
        filters={(
          <TextField
            select
            size="small"
            label="Company"
            value={companyInput}
            onChange={(event) => setCompanyInput(event.target.value)}
            sx={{ minWidth: '14rem' }}
          >
            <MenuItem value="">All companies</MenuItem>
            {companyOptions.map((company) => (
              <MenuItem key={company.id} value={company.id}>
                {company.name}
              </MenuItem>
            ))}
          </TextField>
        )}
        actions={(
          <Button
            variant="contained"
            startIcon={<PlusOutlined />}
            onClick={() =>
              setFormState({ open: true, mode: 'create', deal: null })
            }
          >
            Add Deal
          </Button>
        )}
        loading={dealsQuery.isLoading}
        error={
          dealsQuery.isError && !isTransportError(dealsQuery.error)
            ? extractErrorMessage(dealsQuery.error, 'Failed to load deals.')
            : null
        }
        isEmpty={!dealsQuery.isLoading && !dealsQuery.isError && deals.length === 0}
        emptyTitle="No matching deals"
        emptyDescription="Try broadening stage/company filters or clearing filters."
        pagination={
          dealPage && dealPage.total > 0 ? (
            <Box sx={{ display: 'flex', width: '100%', justifyContent: 'center' }}>
              <DataTablePagination
                page={dealPage.page}
                pageSize={dealPage.pageSize}
                total={dealPage.total}
                totalPages={dealPage.totalPages}
                onPageChange={(page) =>
                  setListQuery((current) => ({ ...current, page }))
                }
                onPageSizeChange={(pageSize) =>
                  setListQuery((current) => ({ ...current, page: 1, pageSize }))
                }
              />
            </Box>
          ) : null
        }
      >
        <DealTable
          deals={deals}
          companiesById={companiesById}
          onView={(deal) => navigate(`/deals/${deal.id}`)}
          onEdit={(deal) => setFormState({ open: true, mode: 'edit', deal })}
        />
      </DataTableShell>

      <DealFormDialog
        open={formState.open}
        mode={formState.mode}
        initialValues={formState.deal}
        isPending={createDeal.isPending || updateDeal.isPending}
        onClose={() => setFormState({ open: false, mode: 'create', deal: null })}
        onSubmit={handleSubmit}
      />

      <Snackbar
        open={feedback.open}
        autoHideDuration={3200}
        onClose={() => setFeedback((current) => ({ ...current, open: false }))}
      >
        <Alert
          onClose={() => setFeedback((current) => ({ ...current, open: false }))}
          severity={feedback.severity}
          variant="filled"
        >
          {feedback.message}
        </Alert>
      </Snackbar>
    </Stack>
  );
}

import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';

import { dealApi } from '../../api/dealApi';

export const dealKeys = {
  all: ['deals'],
  lists: () => [...dealKeys.all, 'list'],
  list: (query) => [...dealKeys.lists(), query],
  details: () => [...dealKeys.all, 'detail'],
  detail: (id) => [...dealKeys.details(), id],
};

export function useDealList(query = {}) {
  return useQuery({
    queryKey: dealKeys.list(query),
    queryFn: () => dealApi.list(query),
  });
}

export function useDeal(id) {
  return useQuery({
    queryKey: dealKeys.detail(id),
    queryFn: () => dealApi.get(id),
    enabled: Boolean(id),
  });
}

export function useCreateDeal() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (data) => dealApi.create(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: dealKeys.lists() });
    },
  });
}

export function useUpdateDeal() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ id, data }) => dealApi.update(id, data),
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: dealKeys.lists() });
      queryClient.invalidateQueries({ queryKey: dealKeys.detail(variables.id) });
    },
  });
}
