import { beforeEach, describe, expect, it, vi } from 'vitest';

import { RequestError, isTransportError, request } from './request';

function createResponse({ status = 200, body = '', statusText = '' } = {}) {
  return {
    ok: status >= 200 && status < 300,
    status,
    statusText,
    text: vi.fn().mockResolvedValue(body),
  };
}

describe('request', () => {
  beforeEach(() => {
    vi.stubGlobal('fetch', vi.fn());
  });

  it('serializes query parameters and omits empty values', async () => {
    fetch.mockResolvedValue(createResponse({ body: JSON.stringify({ items: [] }) }));

    await request('/companies', {
      query: {
        page: 1,
        status: '0',
        q: '',
        industry: undefined,
        owner: null,
      },
    });

    expect(fetch).toHaveBeenCalledWith(
      '/api/companies?page=1&status=0',
      expect.objectContaining({
        headers: {
          'Content-Type': 'application/json',
        },
      }),
    );
  });

  it('allows callers to override default headers', async () => {
    fetch.mockResolvedValue(createResponse({ body: JSON.stringify({ ok: true }) }));

    await request('/companies', {
      headers: {
        'Content-Type': 'application/merge-patch+json',
        Authorization: 'Bearer test-token',
      },
    });

    expect(fetch).toHaveBeenCalledWith(
      '/api/companies',
      expect.objectContaining({
        headers: {
          'Content-Type': 'application/merge-patch+json',
          Authorization: 'Bearer test-token',
        },
      }),
    );
  });

  it('returns parsed JSON for a successful response', async () => {
    fetch.mockResolvedValue(createResponse({ body: JSON.stringify({ id: 'company-1' }) }));

    await expect(request('/companies/company-1')).resolves.toEqual({ id: 'company-1' });
  });

  it('returns null for a successful empty response', async () => {
    fetch.mockResolvedValue(createResponse({ status: 204 }));

    await expect(
      request('/companies/company-1', { method: 'DELETE' }),
    ).resolves.toBeNull();
  });

  it('joins array validation messages in a RequestError', async () => {
    fetch.mockResolvedValue(
      createResponse({
        status: 422,
        body: JSON.stringify({ message: ['Name is required', 'Email is invalid'] }),
      }),
    );

    await expect(request('/companies')).rejects.toMatchObject({
      name: 'RequestError',
      status: 422,
      message: 'Name is required, Email is invalid',
    });
  });

  it('uses statusText when an error response has no message', async () => {
    fetch.mockResolvedValue(
      createResponse({
        status: 404,
        statusText: 'Not Found',
        body: JSON.stringify({}),
      }),
    );

    await expect(request('/companies/missing')).rejects.toMatchObject({
      status: 404,
      message: 'Not Found',
    });
  });

  it('converts a rejected fetch into a network RequestError', async () => {
    fetch.mockRejectedValue(new TypeError('Failed to fetch'));

    await expect(request('/companies')).rejects.toMatchObject({
      name: 'RequestError',
      status: undefined,
      message: 'Network error, please check your connection and try again.',
    });
  });
});

describe('isTransportError', () => {
  it('classifies network and 5xx failures as transport errors', () => {
    expect(isTransportError(new RequestError('Network error', undefined))).toBe(true);
    expect(isTransportError(new RequestError('Unavailable', 503))).toBe(true);
  });

  it('classifies 4xx failures as business errors', () => {
    expect(isTransportError(new RequestError('Conflict', 409))).toBe(false);
    expect(isTransportError(new RequestError('Invalid input', 422))).toBe(false);
  });
});

import { HttpStatus, Injectable } from '@nestjs/common';
import { DataSource } from 'typeorm';
import { AppException } from '../../common/errors/app-exception';
import { BUSINESS_ERROR_CODES } from '../../common/errors/error-codes';
import { CompanyService } from '../company/company.module';
import {
  CreateDealDto,
  DealContactLinkInputDto,
  DealListQueryDto,
  UpdateDealDto,
} from './dto';
import { DealEntity } from './deal.entity';
import { DealContactLinkSummary, DealRepository } from './deal.repository';

type DealResponse = DealEntity & {
  primaryContactId: string | null;
  contactLinks: DealContactLinkSummary[];
  company?: {
    id: string;
    name: string;
  };
};

@Injectable()
export class DealService {
  constructor(
    private readonly dealRepository: DealRepository,
    private readonly companyService: CompanyService,
    private readonly dataSource: DataSource,
  ) {}

  async createDeal(dto: CreateDealDto): Promise<DealResponse> {
    await this.assertCompanyExists(dto.companyId);

    const contactLinks = this.normalizeContactLinks(dto.contactLinks);
    await this.assertContactsExistAndMatchCompany({
      companyId: dto.companyId,
      contactIds: contactLinks.map((link) => link.contactId),
    });

    const primaryContactId = this.resolvePrimaryContactId({
      requestedPrimaryContactId: dto.primaryContactId,
      contactLinks,
      existingPrimaryContactId: null,
      autoSelectWhenSingle: true,
    });

    const deal = await this.dataSource.transaction(async (manager) => {
      const dealRepository = manager.getRepository(DealEntity);
      const createdDeal = dealRepository.create({
        name: dto.name,
        value: dto.value,
        stage: dto.stage ?? 'lead',
        companyId: dto.companyId,
        primaryContactId,
        expectedCloseDate: dto.expectedCloseDate ?? null,
      });

      const savedDeal = await dealRepository.save(createdDeal);

      if (contactLinks.length > 0) {
        await manager
          .createQueryBuilder()
          .insert()
          .into('deal_contact_links')
          .values(
            contactLinks.map((link) => ({
              dealId: savedDeal.id,
              contactId: link.contactId,
              role: link.role,
            })),
          )
          .execute();
      }

      return savedDeal;
    });

    return await this.getDealWithCompany(deal.id);
  }

  async getDeals(query: DealListQueryDto) {
    const result = await this.dealRepository.findWithFilter(query);
    const linksByDealId = await this.dealRepository.findContactLinksByDealIds(
      result.items.map((item) => item.id),
    );

    return {
      ...result,
      items: result.items.map((item) =>
        this.toDealResponse(item, linksByDealId.get(item.id) ?? []),
      ),
    };
  }

  async getDealById(id: string): Promise<DealEntity> {
    const deal = await this.dealRepository.findOne({ where: { id } });

    if (!deal) {
      throw this.createNotFoundException({
        resource: 'Deal',
        id,
        message: `Deal with ID ${id} not found`,
      });
    }

    return deal;
  }

  async getDealWithCompany(id: string): Promise<DealResponse> {
    const deal = await this.getDealById(id);
    const company = await this.companyService.getCompanyById(deal.companyId);
    const contactLinks = await this.dealRepository.findContactLinksByDealId(id);

    return this.toDealResponse(deal, contactLinks, {
      id: company.id,
      name: company.name,
    });
  }

  async updateDeal(id: string, dto: UpdateDealDto): Promise<DealResponse> {
    if (Object.keys(dto).length === 0) {
      throw new AppException({
        statusCode: HttpStatus.BAD_REQUEST,
        code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
        message: 'At least one field must be provided for update.',
        details: {
          errors: [
            {
              field: 'body',
              messages: ['At least one field must be provided for update.'],
            },
          ],
        },
      });
    }

    const deal = await this.getDealById(id);

    const existingContactLinks =
      dto.contactLinks === undefined
        ? await this.dealRepository.findContactLinksByDealId(id)
        : [];

    const nextContactLinks =
      dto.contactLinks !== undefined
        ? this.normalizeContactLinks(dto.contactLinks)
        : existingContactLinks;

    if (dto.contactLinks !== undefined) {
      await this.assertContactsExistAndMatchCompany({
        companyId: deal.companyId,
        contactIds: nextContactLinks.map((link) => link.contactId),
      });
    }

    const primaryContactId = this.resolvePrimaryContactId({
      requestedPrimaryContactId: dto.primaryContactId,
      contactLinks: nextContactLinks,
      existingPrimaryContactId: deal.primaryContactId,
      autoSelectWhenSingle: dto.contactLinks !== undefined,
    });

    await this.dataSource.transaction(async (manager) => {
      const dealRepository = manager.getRepository(DealEntity);
      const existingDeal = await dealRepository.findOne({ where: { id } });

      if (!existingDeal) {
        throw this.createNotFoundException({
          resource: 'Deal',
          id,
          message: `Deal with ID ${id} not found`,
        });
      }

      const updatePayload: Partial<DealEntity> = {
        ...(dto.name !== undefined ? { name: dto.name } : {}),
        ...(dto.value !== undefined ? { value: dto.value } : {}),
        ...(dto.stage !== undefined ? { stage: dto.stage } : {}),
        ...(dto.expectedCloseDate !== undefined
          ? { expectedCloseDate: dto.expectedCloseDate }
          : {}),
        primaryContactId,
      };

      const updatedDeal = dealRepository.merge(existingDeal, updatePayload);
      await dealRepository.save(updatedDeal);

      if (dto.contactLinks !== undefined) {
        await manager
          .createQueryBuilder()
          .delete()
          .from('deal_contact_links')
          .where('"dealId" = :dealId', { dealId: id })
          .execute();

        if (nextContactLinks.length > 0) {
          await manager
            .createQueryBuilder()
            .insert()
            .into('deal_contact_links')
            .values(
              nextContactLinks.map((link) => ({
                dealId: id,
                contactId: link.contactId,
                role: link.role,
              })),
            )
            .execute();
        }
      }
    });

    return await this.getDealWithCompany(id);
  }

  private async assertCompanyExists(companyId: string) {
    try {
      await this.companyService.getCompanyById(companyId);
    } catch (error) {
      if (error instanceof AppException && error.getStatus() === 404) {
        throw this.createNotFoundException({
          resource: 'Company',
          id: companyId,
          message: `Company with ID ${companyId} not found`,
        });
      }

      throw error;
    }
  }

  private async assertContactsExistAndMatchCompany(input: {
    companyId: string;
    contactIds: string[];
  }) {
    const uniqueContactIds = [...new Set(input.contactIds)];

    if (uniqueContactIds.length === 0) {
      return;
    }

    const rows = await this.dataSource
      .createQueryBuilder()
      .select('contact.id', 'id')
      .addSelect('COUNT(link."companyId")', 'companyLinkCount')
      .from('contacts', 'contact')
      .leftJoin(
        'contact_company_links',
        'link',
        'link."contactId" = contact.id AND link."companyId" = :companyId',
        { companyId: input.companyId },
      )
      .where('contact.id IN (:...contactIds)', { contactIds: uniqueContactIds })
      .groupBy('contact.id')
      .getRawMany<{
        id: string;
        companyLinkCount: string;
      }>();

    const byContactId = new Map(rows.map((row) => [row.id, row]));

    uniqueContactIds.forEach((contactId) => {
      const row = byContactId.get(contactId);

      if (!row || Number(row.companyLinkCount) === 0) {
        throw this.createNotFoundException({
          resource: 'Contact',
          id: contactId,
          message: `Contact with ID ${contactId} not found`,
        });
      }
    });
  }

  private normalizeContactLinks(
    contactLinks: DealContactLinkInputDto[] | undefined,
  ): DealContactLinkSummary[] {
    if (!contactLinks) {
      return [];
    }

    const normalizedLinks = contactLinks.map((contactLink) => ({
      contactId: contactLink.contactId,
      role:
        contactLink.role === undefined || contactLink.role === null
          ? null
          : contactLink.role.trim() || null,
    }));

    const uniqueContactIds = new Set(
      normalizedLinks.map((contactLink) => contactLink.contactId),
    );

    if (uniqueContactIds.size !== normalizedLinks.length) {
      throw this.createValidationException({
        field: 'contactLinks',
        message: 'Duplicate contact links are not allowed.',
      });
    }

    return normalizedLinks;
  }

  private resolvePrimaryContactId(input: {
    requestedPrimaryContactId: string | null | undefined;
    contactLinks: DealContactLinkSummary[];
    existingPrimaryContactId: string | null;
    autoSelectWhenSingle: boolean;
  }): string | null {
    const {
      requestedPrimaryContactId,
      contactLinks,
      existingPrimaryContactId,
    } = input;
    const contactIds = new Set(
      contactLinks.map((contactLink) => contactLink.contactId),
    );

    let resolvedPrimaryContactId: string | null;

    if (requestedPrimaryContactId !== undefined) {
      resolvedPrimaryContactId = requestedPrimaryContactId;
    } else if (
      existingPrimaryContactId &&
      contactIds.has(existingPrimaryContactId)
    ) {
      resolvedPrimaryContactId = existingPrimaryContactId;
    } else if (input.autoSelectWhenSingle && contactLinks.length === 1) {
      resolvedPrimaryContactId = contactLinks[0].contactId;
    } else {
      resolvedPrimaryContactId = null;
    }

    if (
      resolvedPrimaryContactId !== null &&
      !contactIds.has(resolvedPrimaryContactId)
    ) {
      throw this.createValidationException({
        field: 'primaryContactId',
        message:
          'primaryContactId must reference one of the deal contactLinks.contactId values.',
      });
    }

    return resolvedPrimaryContactId;
  }

  private toDealResponse(
    deal: DealEntity,
    contactLinks: DealContactLinkSummary[],
    company?: { id: string; name: string },
  ): DealResponse {
    return {
      ...deal,
      ...(company ? { company } : {}),
      contactLinks,
      primaryContactId: deal.primaryContactId ?? null,
    };
  }

  private createNotFoundException(input: {
    resource: 'Deal' | 'Company' | 'Contact';
    id: string;
    message: string;
  }) {
    const { resource, id, message } = input;

    return new AppException({
      statusCode: HttpStatus.NOT_FOUND,
      code: BUSINESS_ERROR_CODES.NOT_FOUND,
      message,
      details: {
        resource,
        id,
      },
    });
  }

  private createValidationException(input: { field: string; message: string }) {
