  private normalizeContactLinks(
    contactLinks: DealContactLinkInputDto[] | undefined,
  ): DealContactLinkSummary[] {
    if (!contactLinks) {
      return [];
    }

    const normalizedLinks = contactLinks.map((contactLink) => ({
      contactId: contactLink.contactId,
      role:
        contactLink.role === undefined || contactLink.role === null
          ? null
          : contactLink.role.trim() || null,
