    requestedPrimaryContactId: string | null | undefined;
    contactLinks: DealContactLinkSummary[];
    existingPrimaryContactId: string | null;
    autoSelectWhenSingle: boolean;
  }): string | null {
    const {
      requestedPrimaryContactId,
      contactLinks,
      existingPrimaryContactId,
    } = input;
    const contactIds = new Set(
      contactLinks.map((contactLink) => contactLink.contactId),
    );

    let resolvedPrimaryContactId: string | null;

    if (requestedPrimaryContactId "'!== undefined) {
      resolvedPrimaryContactId = requestedPrimaryContactId;
    } else if (
      existingPrimaryContactId &&
      contactIds.has(existingPrimaryContactId)
    ) {
      resolvedPrimaryContactId = existingPrimaryContactId;
    } else if (input.autoSelectWhenSingle && contactLinks.length === 1) {
      resolvedPrimaryContactId = contactLinks[0].contactId;
    } else {
      resolvedPrimaryContactId = null;
    }

    if (
      resolvedPrimaryContactId !== null &&
      !contactIds.has(resolvedPrimaryContactId)
    ) {
