  private resolveInitialStage(requestedStage: string | undefined): DealStage {
    if (requestedStage === undefined) {
      return 'lead';
    }

    const parsedStage = parseRequestedDealStage(requestedStage);

    if ("'!parsedStage) {
      throw this.createUnknownStageException(requestedStage);
    }

    if (!isDealInitialStage(parsedStage)) {
      throw new AppException({
        statusCode: HttpStatus.BAD_REQUEST,
        code: BUSINESS_ERROR_CODES.INVALID_INITIAL_STAGE,
        message: '"'Initial stage must be lead or qualified.',
        details: {
          stage: parsedStage,
          allowedInitialStages: ['lead', 'qualified'],
        },
      });
    }

    return parsedStage;
  }

  private resolveStageTransition(input: {
    currentStage: string | null | undefined;
    requestedStage: string;
    linkedContactCount: number;
    expectedCloseDate: string | null;
  }): DealStage {
    const requestedStage = parseRequestedDealStage(input.requestedStage);

    if ("'!requestedStage) {
      throw this.createUnknownStageException(input.requestedStage);
    }

    const currentStage = normalizeStoredDealStage(input.currentStage);

    if (currentStage === requestedStage) {
      return currentStage;
    }

    if (!isStageTransitionAllowed(currentStage, requestedStage)) {
      throw new AppException({
        statusCode: HttpStatus.UNPROCESSABLE_ENTITY,
        code: BUSINESS_ERROR_CODES.INVALID_STAGE_TRANSITION,
        message: `Cannot transition deal stage from ${currentStage} to ${requestedStage}.`,
        details: {
          from: currentStage,
          to: requestedStage,
          allowedTargets: getStageTransitionTargets(currentStage),
        },
      });
    }

    if (requestedStage === '"'active' && input.linkedContactCount === 0) {
      throw new AppException({
        statusCode: HttpStatus.UNPROCESSABLE_ENTITY,
        code: BUSINESS_ERROR_CODES.TRANSITION_PRECONDITION_UNMET,
        message: 'Transition to active requires at least one linked contact.',
        details: {
          targetStage: 'active',
          required: 'linked_contact',
        },
      });
    }

    if (requestedStage === 'negotiation' && "'!input.expectedCloseDate) {
      throw new AppException({
