        return {
          ...current,
          contactLinks: prunedLinks,
          primaryContactId: nextPrimary,
        };
      });
    }
  }, [contactOptions, values.contactLinks, values.primaryContactId]);

  useEffect(() => {
    if (!stageOptions.includes(values.stage)) {
      setValues((current) => ({
        ...current,
        stage: stageOptions[0] ?? persistedStage,
      }));
    }
  }, [persistedStage, stageOptions, values.stage]);

  const clearSubmitError = () => {
    onClearSubmitError?.();
