    setValues((current) => ({
      ...current,
      contactLinks: current.contactLinks.map((contactLink) =>
        contactLink.contactId === contactId
          ? { ...contactLink, role }
          : contactLink,
      ),
    }));
  };

  const handlePrimaryContactChange = (contactId) => {
