import { HttpStatus, Injectable } from '@nestjs/common';
import { DataSource } from 'typeorm';
import { AppException } from '../../common/errors/app-exception';
import { BUSINESS_ERROR_CODES } from '../../common/errors/error-codes';
import { CompanyService } from '../company/company.module';
import {
  CreateDealDto,
  DealContactLinkInputDto,
  DealListQueryDto,
  UpdateDealDto,
  UpdateDealStageDto,
} from './dto';
import {
  DealStage,
  getStageTransitionTargets,
  isDealInitialStage,
  isStageTransitionAllowed,
  normalizeStoredDealStage,
  parseRequestedDealStage,
} from './deal-stage.policy';
import { DealEntity } from './deal.entity';
import { DealContactLinkSummary, DealRepository } from './deal.repository';

type DealResponse = DealEntity & {
  primaryContactId: string | null;
  contactLinks: DealContactLinkSummary[];
  company?: {
    id: string;
    name: string;
  };
};

@Injectable()
export class DealService {
  constructor(
    private readonly dealRepository: DealRepository,
    private readonly companyService: CompanyService,
    private readonly dataSource: DataSource,
  ) {}

  async createDeal(dto: CreateDealDto): Promise<DealResponse> {
    await this.assertCompanyExists(dto.companyId);

    const contactLinks = this.normalizeContactLinks(dto.contactLinks);
    await this.assertContactsExistAndMatchCompany({
      companyId: dto.companyId,
      contactIds: contactLinks.map((link) => link.contactId),
    });

    const primaryContactId = this.resolvePrimaryContactId({
      requestedPrimaryContactId: dto.primaryContactId,
      contactLinks,
      existingPrimaryContactId: null,
      autoSelectWhenSingle: true,
    });

    const initialStage = this.resolveInitialStage(dto.stage);

    const deal = await this.dataSource.transaction(async (manager) => {
      const dealRepository = manager.getRepository(DealEntity);
      const createdDeal = dealRepository.create({
        name: dto.name,
        value: dto.value,
        stage: initialStage,
        companyId: dto.companyId,
        primaryContactId,
        expectedCloseDate: dto.expectedCloseDate ?? null,
      });

      const savedDeal = await dealRepository.save(createdDeal);

      if (contactLinks.length > 0) {
        await manager
          .createQueryBuilder()
          .insert()
          .into('deal_contact_links')
          .values(
            contactLinks.map((link) => ({
              dealId: savedDeal.id,
              contactId: link.contactId,
              role: link.role,
            })),
          )
          .execute();
      }

      return savedDeal;
    });

    return await this.getDealWithCompany(deal.id);
  }

  async getDeals(query: DealListQueryDto) {
    const result = await this.dealRepository.findWithFilter(query);
    const linksByDealId = await this.dealRepository.findContactLinksByDealIds(
      result.items.map((item) => item.id),
    );

    return {
      ...result,
      items: result.items.map((item) =>
        this.toDealResponse(item, linksByDealId.get(item.id) ?? []),
      ),
    };
  }

  async getDealById(id: string): Promise<DealEntity> {
    const deal = await this.dealRepository.findOne({ where: { id } });

    if (!deal) {
      throw this.createNotFoundException({
        resource: 'Deal',
        id,
        message: `Deal with ID ${id} not found`,
      });
    }

    return deal;
  }

  async getDealWithCompany(id: string): Promise<DealResponse> {
    const deal = await this.getDealById(id);
    const company = await this.companyService.getCompanyById(deal.companyId);
    const contactLinks = await this.dealRepository.findContactLinksByDealId(id);

    return this.toDealResponse(deal, contactLinks, {
      id: company.id,
      name: company.name,
    });
  }

  async updateDeal(id: string, dto: UpdateDealDto): Promise<DealResponse> {
    if (Object.keys(dto).length === 0) {
      throw new AppException({
        statusCode: HttpStatus.BAD_REQUEST,
        code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
        message: 'At least one field must be provided for update.',
        details: {
          errors: [
            {
              field: 'body',
              messages: ['At least one field must be provided for update.'],
            },
          ],
        },
      });
    }

    const deal = await this.getDealById(id);

    const existingContactLinks =
      dto.contactLinks === undefined
        ? await this.dealRepository.findContactLinksByDealId(id)
        : [];

    const nextContactLinks =
      dto.contactLinks !== undefined
        ? this.normalizeContactLinks(dto.contactLinks)
        : existingContactLinks;

    if (dto.contactLinks !== undefined) {
      await this.assertContactsExistAndMatchCompany({
        companyId: deal.companyId,
        contactIds: nextContactLinks.map((link) => link.contactId),
      });
    }

    const primaryContactId = this.resolvePrimaryContactId({
      requestedPrimaryContactId: dto.primaryContactId,
      contactLinks: nextContactLinks,
      existingPrimaryContactId: deal.primaryContactId,
      autoSelectWhenSingle: dto.contactLinks !== undefined,
    });

    const stage =
      dto.stage === undefined
        ? undefined
        : this.resolveStageTransition({
            currentStage: deal.stage,
            requestedStage: dto.stage,
            linkedContactCount: nextContactLinks.length,
            expectedCloseDate:
              dto.expectedCloseDate !== undefined
                ? dto.expectedCloseDate
                : deal.expectedCloseDate,
          });

    await this.dataSource.transaction(async (manager) => {
      const dealRepository = manager.getRepository(DealEntity);
      const existingDeal = await dealRepository.findOne({ where: { id } });

      if (!existingDeal) {
        throw this.createNotFoundException({
          resource: 'Deal',
          id,
          message: `Deal with ID ${id} not found`,
        });
      }

      const updatePayload: Partial<DealEntity> = {
        ...(dto.name !== undefined ? { name: dto.name } : {}),
        ...(dto.value !== undefined ? { value: dto.value } : {}),
        ...(stage !== undefined ? { stage } : {}),
        ...(dto.expectedCloseDate !== undefined
          ? { expectedCloseDate: dto.expectedCloseDate }
          : {}),
        primaryContactId,
      };

      const updatedDeal = dealRepository.merge(existingDeal, updatePayload);
      await dealRepository.save(updatedDeal);

      if (dto.contactLinks !== undefined) {
        await manager
          .createQueryBuilder()
          .delete()
          .from('deal_contact_links')
          .where('"dealId" = :dealId', { dealId: id })
          .execute();

        if (nextContactLinks.length > 0) {
          await manager
            .createQueryBuilder()
            .insert()
            .into('deal_contact_links')
            .values(
              nextContactLinks.map((link) => ({
                dealId: id,
                contactId: link.contactId,
                role: link.role,
              })),
            )
            .execute();
        }
      }
    });

    return await this.getDealWithCompany(id);
  }

  async transitionDealStage(
    id: string,
    dto: UpdateDealStageDto,
  ): Promise<DealResponse> {
    const deal = await this.getDealById(id);
    const existingContactLinks =
      await this.dealRepository.findContactLinksByDealId(id);

    const stage = this.resolveStageTransition({
      currentStage: deal.stage,
      requestedStage: dto.stage,
      linkedContactCount: existingContactLinks.length,
      expectedCloseDate: deal.expectedCloseDate,
    });

    await this.dataSource.transaction(async (manager) => {
      const dealRepository = manager.getRepository(DealEntity);
      const existingDeal = await dealRepository.findOne({ where: { id } });

      if (!existingDeal) {

    if (!existingDeal) {
      throw this.createNotFoundException({
        resource: 'Deal',
        id,
        message: `Deal with ID ${id} not found`,
      });
    }

    if (existingDeal.stage === stage) {
      return;
    }

    existingDeal.stage = stage;
    await dealRepository.save(existingDeal);
  });

  return await this.getDealWithCompany(id);
}

private async assertCompanyExists(companyId: string) {
  try {
    await this.companyService.getCompanyById(companyId);
  } catch (error) {
    if (error instanceof AppException && error.getStatus() === 404) {
      throw this.createNotFoundException({
        resource: 'Company',
        id: companyId,
        message: `Company with ID ${companyId} not found`,
      });
    }

    throw error;
  }
}

private async assertContactsExistAndMatchCompany(input: {
  companyId: string;
  contactIds: string[];
}) {
  const uniqueContactIds = [...new Set(input.contactIds)];

  if (uniqueContactIds.length === 0) {
    return;
  }

  const rows = await this.dataSource
    .createQueryBuilder()
    .select('contact.id', 'id')
    .addSelect('COUNT(link."companyId")', 'companyLinkCount')
    .from('contacts', 'contact')
    .leftJoin(
      'contact_company_links',
      'link',
      'link."contactId" = contact.id AND link."companyId" = :companyId',
      { companyId: input.companyId },
    )
    .where('contact.id IN (:...contactIds)', { contactIds: uniqueContactIds })
    .groupBy('contact.id')
    .getRawMany<{
      id: string;
      companyLinkCount: string;
    }>();

  const byContactId = new Map(rows.map((row) => [row.id, row]));

  uniqueContactIds.forEach((contactId) => {
    const row = byContactId.get(contactId);

    if (!row || Number(row.companyLinkCount) === 0) {
      throw this.createNotFoundException({
        resource: 'Contact',
        id: contactId,
        message: `Contact with ID ${contactId} not found`,
      });
    }
  });
}

private normalizeContactLinks(
  contactLinks: DealContactLinkInputDto[] | undefined,
): DealContactLinkSummary[] {
  if (!contactLinks) {
    return [];
  }

  const normalizedLinks = contactLinks.map((contactLink) => ({
    contactId: contactLink.contactId,
    role:
      contactLink.role === undefined || contactLink.role === null
        ? null
        : contactLink.role.trim() || null,
  }));

  const uniqueContactIds = new Set(
    normalizedLinks.map((contactLink) => contactLink.contactId),
  );

  if (uniqueContactIds.size !== normalizedLinks.length) {
    throw this.createValidationException({
      field: 'contactLinks',
      message: 'Duplicate contact links are not allowed.',
    });
  }

  return normalizedLinks;
}

private resolvePrimaryContactId(input: {
  requestedPrimaryContactId: string | null | undefined;
  contactLinks: DealContactLinkSummary[];
  existingPrimaryContactId: string | null;
  autoSelectWhenSingle: boolean;
}): string | null {
  const {
    requestedPrimaryContactId,
    contactLinks,
    existingPrimaryContactId,
  } = input;
  const contactIds = new Set(
    contactLinks.map((contactLink) => contactLink.contactId),
  );

  let resolvedPrimaryContactId: string | null;

  if (requestedPrimaryContactId !== undefined) {
    resolvedPrimaryContactId = requestedPrimaryContactId;
  } else if (
    existingPrimaryContactId &&
    contactIds.has(existingPrimaryContactId)
  ) {
    resolvedPrimaryContactId = existingPrimaryContactId;
  } else if (input.autoSelectWhenSingle && contactLinks.length === 1) {
    resolvedPrimaryContactId = contactLinks[0].contactId;
  } else {
    resolvedPrimaryContactId = null;
  }

  if (
    resolvedPrimaryContactId !== null &&
    !contactIds.has(resolvedPrimaryContactId)
  ) {
    throw this.createValidationException({
      field: 'primaryContactId',
      message:
        'primaryContactId must reference one of the deal contactLinks.contactId values.',
    });
  }

  return resolvedPrimaryContactId;
}

private resolveInitialStage(requestedStage: string | undefined): DealStage {
  if (requestedStage === undefined) {
    return 'lead';
  }

  const parsedStage = parseRequestedDealStage(requestedStage);

  if (!parsedStage) {
    throw this.createUnknownStageException(requestedStage);
  }

  if (!isDealInitialStage(parsedStage)) {
    throw new AppException({
      statusCode: HttpStatus.BAD_REQUEST,
      code: BUSINESS_ERROR_CODES.INVALID_INITIAL_STAGE,
      message: 'Initial stage must be lead or qualified.',
      details: {
        stage: parsedStage,
        allowedInitialStages: ['lead', 'qualified'],
      },
    });
  }

  return parsedStage;
}

private resolveStageTransition(input: {
  currentStage: string | null | undefined;
  requestedStage: string;
  linkedContactCount: number;
  expectedCloseDate: string | null;
}): DealStage {
  const requestedStage = parseRequestedDealStage(input.requestedStage);

  if (!requestedStage) {
    throw this.createUnknownStageException(input.requestedStage);
  }

  const currentStage = normalizeStoredDealStage(input.currentStage);

  if (currentStage === requestedStage) {
    return currentStage;
  }

  if (!isStageTransitionAllowed(currentStage, requestedStage)) {
    throw new AppException({
      statusCode: HttpStatus.UNPROCESSABLE_ENTITY,
      code: BUSINESS_ERROR_CODES.INVALID_STAGE_TRANSITION,
      message: `Cannot transition deal stage from ${currentStage} to ${requestedStage}.`,
      details: {
        from: currentStage,
        to: requestedStage,
        allowedTargets: getStageTransitionTargets(currentStage),
      },
    });
  }

  if (requestedStage === 'active' && input.linkedContactCount === 0) {
    throw new AppException({
      statusCode: HttpStatus.UNPROCESSABLE_ENTITY,
      code: BUSINESS_ERROR_CODES.TRANSITION_PRECONDITION_UNMET,
      message: 'Transition to active requires at least one linked contact.',
      details: {
        targetStage: 'active',
        required: 'linked_contact',
      },
    });
  }

  if (requestedStage === 'negotiation' && !input.expectedCloseDate) {
    throw new AppException({
      statusCode: HttpStatus.UNPROCESSABLE_ENTITY,
      code: BUSINESS_ERROR_CODES.TRANSITION_PRECONDITION_UNMET,
      message:
        'Transition to negotiation requires a non-null expectedCloseDate.',
      details: {
        targetStage: 'negotiation',
        required: 'expected_close_date',
      },
    });
  }

  return requestedStage;
}

private toDealResponse(
  deal: DealEntity,
  contactLinks: DealContactLinkSummary[],
  company?: { id: string; name: string },
): DealResponse {
  return {
    ...deal,
    stage: normalizeStoredDealStage(deal.stage),
    ...(company ? { company } : {}),
    contactLinks,
    primaryContactId: deal.primaryContactId ?? null,
  };
}

private createNotFoundException(input: {
  resource: 'Deal' | 'Company' | 'Contact';
  id: string;
  message: string;
}) {
  const { resource, id, message } = input;

  return new AppException({
    statusCode: HttpStatus.NOT_FOUND,
    code: BUSINESS_ERROR_CODES.NOT_FOUND,
    message,

      message,
      details: {
        resource,
        id,
      },
    });
  }

  private createUnknownStageException(stage: string) {
    return new AppException({
      statusCode: HttpStatus.BAD_REQUEST,
      code: BUSINESS_ERROR_CODES.UNKNOWN_STAGE,
      message: `Unknown deal stage: ${stage}`,
      details: {
        stage,
      },
    });
  }

  private createValidationException(input: { field: string; message: string }) {
    return new AppException({
      statusCode: HttpStatus.BAD_REQUEST,
      code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
      message: input.message,
      details: {
        errors: [
          {
            field: input.field,
            messages: [input.message],
          },
        ],
      },
    });
  }
}

import {
  Alert,
  Box,
  Button,
  MenuItem,
  Snackbar,
  Stack,
  TextField,
} from '@mui/material';
import PlusOutlined from '@ant-design/icons/PlusOutlined';
import { useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';

import { isTransportError } from 'api/request';
import { DataTablePagination } from '../../components/Table/Pagination/Pagination';
import { DataTableShell } from '../../components/Table/Shell/Shell';
import { useCompanyList } from '../companies/companyQueries';
import { DealFormDialog } from './DealForm';
import { DealTable } from './DealTable';
import { useCreateDeal, useDealList, useUpdateDeal } from './dealQueries';

function extractErrorMessage(error, fallbackMessage) {
  return error?.message || fallbackMessage;
}

const INLINE_STAGE_ERROR_CODES = new Set([
  'UNKNOWN_STAGE',
  'INVALID_INITIAL_STAGE',
  'INVALID_STAGE_TRANSITION',
  'TRANSITION_PRECONDITION_UNMET',
]);

export default function DealsPage() {
  const navigate = useNavigate();
  const createDeal = useCreateDeal();
  const updateDeal = useUpdateDeal();

  const [feedback, setFeedback] = useState({
    open: false,
    severity: 'success',
    message: '',
  });
  const [formState, setFormState] = useState({
    open: false,
    mode: 'create',
    deal: null,
  });
  const [formSubmitError, setFormSubmitError] = useState('');
  const [stageInput, setStageInput] = useState('');
  const [companyInput, setCompanyInput] = useState('');
  const [listQuery, setListQuery] = useState({
    page: 1,
    pageSize: 10,
  });

  const dealsQuery = useDealList(listQuery);
  const companiesQuery = useCompanyList({ page: 1, pageSize: 100 });

  const companyOptions = companiesQuery.data?.items ?? [];
  const companiesById = useMemo(
    () =>
      Object.fromEntries(companyOptions.map((company) => [company.id, company.name])),
    [companyOptions],
  );

  const handleSubmit = async (payload) => {
    try {
      if (formState.mode === 'create') {
        await createDeal.mutateAsync(payload);
        setFeedback({
          open: true,
          severity: 'success',
          message: 'Deal created.',
        });
      } else {
        await updateDeal.mutateAsync({
          id: formState.deal.id,
          data: payload,
        });
        setFeedback({
          open: true,
          severity: 'success',
          message: 'Deal updated.',
        });
      }

      setFormSubmitError('');
      setFormState({ open: false, mode: 'create', deal: null });
    } catch (error) {
      if (!isTransportError(error)) {
        if (INLINE_STAGE_ERROR_CODES.has(error?.code)) {
          setFormSubmitError(extractErrorMessage(error, 'Invalid deal stage request.'));
          return;
        }

        setFeedback({
          open: true,
          severity: 'error',
          message: extractErrorMessage(error, 'Deal request failed.'),
        });
      }
    }
  };

  const handleSearchSubmit = (event) => {
    event.preventDefault();
    setListQuery((current) => ({
      ...current,
      page: 1,
      ...(stageInput.trim() ? { stage: stageInput.trim() } : { stage: undefined }),
      ...(companyInput ? { companyId: companyInput } : { companyId: undefined }),
    }));
  };

  const handleResetFilters = () => {
    setStageInput('');
    setCompanyInput('');
    setListQuery((current) => ({ page: 1, pageSize: current.pageSize }));
  };

  const dealPage = dealsQuery.data;
  const deals = dealPage?.items ?? [];

  return (
    <Stack spacing={3}>
      <DataTableShell
        title="Deals"
        searchValue={stageInput}
        onSearchChange={setStageInput}
        onSearchSubmit={handleSearchSubmit}
        onReset={handleResetFilters}
        searchPlaceholder="Filter by stage (exact)"
        filters={(
          <TextField
            select
            size="small"
            label="Company"
            value={companyInput}
            onChange={(event) => setCompanyInput(event.target.value)}
            sx={{ minWidth: '14rem' }}
          >
            <MenuItem value="">All companies</MenuItem>
            {companyOptions.map((company) => (
              <MenuItem key={company.id} value={company.id}>
                {company.name}
              </MenuItem>
            ))}
          </TextField>
        )}
        actions={(
          <Button
            variant="contained"
            startIcon={<PlusOutlined />}
            onClick={() => {
              setFormSubmitError('');
              setFormState({ open: true, mode: 'create', deal: null });
            }}
          >
            Add Deal
          </Button>
        )}
        loading={dealsQuery.isLoading}
        error={
          dealsQuery.isError && !isTransportError(dealsQuery.error)
            ? extractErrorMessage(dealsQuery.error, 'Failed to load deals.')
            : null
        }
        isEmpty={!dealsQuery.isLoading && !dealsQuery.isError && deals.length === 0}
        emptyTitle="No matching deals"
        emptyDescription="Try broadening stage/company filters or clearing filters."
        pagination={
          dealPage && dealPage.total > 0 ? (
            <Box sx={{ display: 'flex', width: '100%', justifyContent: 'center' }}>
              <DataTablePagination
                page={dealPage.page}
                pageSize={dealPage.pageSize}
                total={dealPage.total}
                totalPages={dealPage.totalPages}
                onPageChange={(page) =>
                  setListQuery((current) => ({ ...current, page }))
                }
                onPageSizeChange={(pageSize) =>
                  setListQuery((current) => ({ ...current, page: 1, pageSize }))
                }
              />
            </Box>
          ) : null
        }
      >
        <DealTable
          deals={deals}
          companiesById={companiesById}
          onView={(deal) => navigate(`/deals/${deal.id}`)}
          onEdit={(deal) => {
            setFormSubmitError('');
            setFormState({ open: true, mode: 'edit', deal });
          }}
        />
      </DataTableShell>

      <DealFormDialog
        open={formState.open}
        mode={formState.mode}
        initialValues={formState.deal}
        isPending={createDeal.isPending || updateDeal.isPending}
        submitError={formSubmitError}
        onClearSubmitError={() => setFormSubmitError('')}
        onClose={() => {
          setFormSubmitError('');
          setFormState({ open: false, mode: 'create', deal: null });
        }}
        onSubmit={handleSubmit}
      />

      <Snackbar
        open={feedback.open}
        autoHideDuration={3200}
        onClose={() => setFeedback((current) => ({ ...current, open: false }))}
      >
        <Alert
          onClose={() => setFeedback((current) => ({ ...current, open: false }))}
          severity={feedback.severity}
          variant="filled"
        >
          {feedback.message}
        </Alert>
      </Snackbar>
    </Stack>
  );
}

const API_BASE_PATH = '/api';

// Thrown by request() for both network failures (status undefined) and non-2xx
// HTTP responses (status set). isTransportError() below is the single source of
// truth for "infra-level failure the global interceptor should toast" vs.
// "business error the calling page should handle and display itself".
export class RequestError extends Error {
  constructor(message, status, code, details) {
    super(message);
    this.name = 'RequestError';
    this.status = status;
    this.code = code;
    this.details = details;
  }
}

// Network failures (fetch itself rejected, no HTTP response at all) and 5xx
// server errors aren't meaningful to a specific page/action, so the global
// interceptor (see App.jsx) shows a generic toast for these. Every other
// status (400/401/403/404/409/422/...) is treated as a business error and
// left to the calling component to interpret and display.
export function isTransportError(error) {
  return !error?.status || error.status >= 500;
}

function buildUrl(path, query) {
  const url = new URL(`${API_BASE_PATH}${path}`, window.location.origin);

  if (query) {
    Object.entries(query).forEach(([key, value]) => {
      if (value !== undefined && value !== null && value !== '') {
        url.searchParams.set(key, value);
      }
    });
  }

  return `${url.pathname}${url.search}`;
}

// vite.config.js proxies /api/* to CRM_BASELINE_API_ORIGIN (backend mounts everything
// under app.setGlobalPrefix('api')), so callers pass paths like '/companies' and this
// prepends the /api prefix + serializes the `query` object as a querystring.
export async function request(path, { query, headers, ...options } = {}) {
  let response;

  try {
    response = await fetch(buildUrl(path, query), {
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...headers,
      },
    });
  } catch {
    throw new RequestError('Network error, please check your connection and try again.', undefined);
  }

  const text = await response.text();
  const data = text ? JSON.parse(text) : null;

  if (!response.ok) {
    const message = data?.message || response.statusText || 'Request failed';
    throw new RequestError(
      Array.isArray(message) ? message.join(', ') : message,
      response.status,
      data?.code,
      data?.details,
    );
  }

  return data;
}

